/**
 * Orders Bounded Context — Domain Layer (self-contained).
 *
 * Aggregate Root: Order. Value Object: Money.
 * Invariants enforced inside the aggregate; state transitions emit domain events.
 */

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

/** Domain error base — allows infrastructure to map to HTTP/RPC codes. */
export class DomainError extends Error {
  constructor(
    message: string,
    readonly code: string,
  ) {
    super(message);
    this.name = new.target.name;
  }
}

export class InvalidMoneyError extends DomainError {
  constructor(message: string) {
    super(message, 'INVALID_MONEY');
  }
}

export class CurrencyMismatchError extends DomainError {
  constructor(left: string, right: string) {
    super(`Cannot operate on different currencies: ${left} vs ${right}`, 'CURRENCY_MISMATCH');
  }
}

export class InvalidQuantityError extends DomainError {
  constructor(quantity: number) {
    super(`Quantity must be a positive integer, received: ${quantity}`, 'INVALID_QUANTITY');
  }
}

export class InvalidOrderStateError extends DomainError {
  constructor(action: string, status: OrderStatus) {
    super(`Cannot ${action} an order in status ${status}`, 'INVALID_ORDER_STATE');
  }
}

export class EmptyOrderError extends DomainError {
  constructor() {
    super('Cannot pay for an order without items', 'EMPTY_ORDER');
  }
}

const CURRENCY_PATTERN = /^[A-Z]{3}$/;
/** Minor-unit scale (cents). Money is stored as integer minor units internally. */
const SCALE = 100;

/** Immutable Value Object: equality by value, never by identity. */
export class Money {
  private readonly minorUnits: number;

  constructor(amount: number, currency: string) {
    if (typeof amount !== 'number' || !Number.isFinite(amount)) {
      throw new InvalidMoneyError(`Amount must be a finite number, received: ${String(amount)}`);
    }
    const normalizedCurrency = currency.trim().toUpperCase();
    if (!CURRENCY_PATTERN.test(normalizedCurrency)) {
      throw new InvalidMoneyError(`Currency must be a 3-letter ISO 4217 code, received: ${currency}`);
    }
    const minorUnits = Math.round(amount * SCALE);
    if (minorUnits < 0) {
      throw new InvalidMoneyError(`Amount cannot be negative, received: ${amount}`);
    }
    this.minorUnits = minorUnits;
    this.currency = normalizedCurrency;
    Object.freeze(this);
  }

  readonly currency: string;

  get amount(): number {
    return this.minorUnits / SCALE;
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  static zero(currency: string): Money {
    return new Money(0, currency);
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money((this.minorUnits + other.minorUnits) / SCALE, this.currency);
  }

  multiply(factor: number): Money {
    if (!Number.isInteger(factor) || factor < 0) {
      throw new InvalidMoneyError(`Factor must be a non-negative integer, received: ${factor}`);
    }
    return new Money((this.minorUnits * factor) / SCALE, this.currency);
  }

  equals(other: Money): boolean {
    return this.currency === other.currency && this.minorUnits === other.minorUnits;
  }

  toString(): string {
    return `${this.amount.toFixed(2)} ${this.currency}`;
  }

  private assertSameCurrency(other: Money): void {
    if (this.currency !== other.currency) {
      throw new CurrencyMismatchError(this.currency, other.currency);
    }
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

export interface DomainEvent {
  readonly name: string;
  readonly aggregateId: string;
  readonly occurredAt: Date;
  readonly payload: Readonly<Record<string, string | number>>;
}

/** Aggregate Root — the only entry point for mutating order state. */
export class Order {
  private readonly mutableItems: OrderItem[] = [];
  private readonly events: DomainEvent[] = [];
  private currentStatus: OrderStatus = 'PENDING';

  constructor(
    readonly id: string,
    readonly customerId: string,
  ) {
    if (id.trim().length === 0) throw new DomainError('Order id is required', 'INVALID_ORDER_ID');
    if (customerId.trim().length === 0) {
      throw new DomainError('Customer id is required', 'INVALID_CUSTOMER_ID');
    }
    this.record('OrderCreated', { customerId });
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this.mutableItems.map((item) => ({ ...item }));
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this.currentStatus !== 'PENDING') throw new InvalidOrderStateError('add items to', this.currentStatus);
    if (productId.trim().length === 0) throw new DomainError('Product id is required', 'INVALID_PRODUCT_ID');
    if (!Number.isInteger(quantity) || quantity <= 0) throw new InvalidQuantityError(quantity);
    const first = this.mutableItems[0];
    if (first !== undefined && first.price.currency !== price.currency) {
      throw new CurrencyMismatchError(first.price.currency, price.currency);
    }
    const existing = this.mutableItems.find((item) => item.id === productId);
    if (existing !== undefined) {
      existing.quantity += quantity;
      existing.price = price;
    } else {
      this.mutableItems.push({ id: productId, quantity, price });
    }
    this.record('OrderItemAdded', { productId, quantity, unitPrice: price.amount, currency: price.currency });
  }

  pay(): void {
    if (this.currentStatus !== 'PENDING') throw new InvalidOrderStateError('pay', this.currentStatus);
    if (this.mutableItems.length === 0) throw new EmptyOrderError();
    this.currentStatus = 'PAID';
    const total = this.getTotal();
    this.record('OrderPaid', { total: total.amount, currency: total.currency });
  }

  ship(): void {
    if (this.currentStatus !== 'PAID') throw new InvalidOrderStateError('ship', this.currentStatus);
    this.currentStatus = 'SHIPPED';
    this.record('OrderShipped', { itemCount: this.mutableItems.length });
  }

  cancel(): void {
    if (this.currentStatus === 'SHIPPED' || this.currentStatus === 'CANCELLED') {
      throw new InvalidOrderStateError('cancel', this.currentStatus);
    }
    const previous = this.currentStatus;
    this.currentStatus = 'CANCELLED';
    this.record('OrderCancelled', { previousStatus: previous });
  }

  getTotal(): Money {
    const first = this.mutableItems[0];
    if (first === undefined) return Money.zero('USD');
    return this.mutableItems.reduce<Money>(
      (sum, item) => sum.add(item.price.multiply(item.quantity)),
      Money.zero(first.price.currency),
    );
  }

  getDomainEvents(): DomainEvent[] {
    return [...this.events];
  }

  pullDomainEvents(): DomainEvent[] {
    return this.events.splice(0, this.events.length);
  }

  private record(name: string, payload: Record<string, string | number>): void {
    this.events.push({ name, aggregateId: this.id, occurredAt: new Date(), payload: Object.freeze({ ...payload }) });
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

/** In-memory repository for tests and local runtime; one repository per aggregate root. */
export class InMemoryOrderRepository implements IOrderRepository {
  private readonly storage = new Map<string, Order>();

  async findById(id: string): Promise<Order | null> {
    return this.storage.get(id) ?? null;
  }

  async save(order: Order): Promise<void> {
    this.storage.set(order.id, order);
  }
}
